111	Thumbs.delete = async function (id, relativePaths, preserveFiles) {
112		const isDraft = validator.isUUID(String(id));
113		const set = `${isDraft ? 'draft' : 'topic'}:${id}:thumbs`;
114	
115		if (typeof relativePaths === 'string') {
116			relativePaths = [relativePaths];
117		} else if (!Array.isArray(relativePaths)) {
118			throw new Error('[[error:invalid-data]]');
119		}
120	
121		const absolutePaths = relativePaths.map(relativePath => path.join(nconf.get('upload_path'), relativePath));
122		const [associated, existsOnDisk] = await Promise.all([
123			db.isSortedSetMembers(set, relativePaths),
124			Promise.all(absolutePaths.map(async absolutePath => file.exists(absolutePath))),
125		]);
126	
127		const toRemove = [];
128		const toDelete = [];
129		relativePaths.forEach((relativePath, idx) => {
130			if (associated[idx]) {
131				toRemove.push(relativePath);
132			}
133	
134			if (existsOnDisk[idx] && !relativePath.startsWith('http')) {
135				toDelete.push(absolutePaths[idx]);
136			}
137		});
138	
139		await db.sortedSetRemove(set, toRemove);
140		if (toRemove.length && !isDraft) {
141			const topics = require('.');
142			const mainPid = (await topics.getMainPids([id]))[0];
143	
144			await Promise.all([
145				db.incrObjectFieldBy(`topic:${id}`, 'numThumbs', -toRemove.length),
146				Promise.all(toRemove.map(async relativePath => posts.uploads.dissociate(mainPid, relativePath.replace('/files/', '')))),
147			]);
148		}
149	
150		if (!preserveFiles) {
151			const pathsToDelete = await Promise.all(toDelete.map(async (absolutePath) => {
152				const relativePath = path.relative(path.join(nconf.get('upload_path'), 'files'), absolutePath);
153				return relativePath && await posts.uploads.isOrphan(relativePath) ? relativePath : null;
154			}));
155			await posts.uploads.deleteFromDisk(pathsToDelete.filter(Boolean));
156		}
157	};
